function renderLessonLibrary() {
  main.innerHTML =
    heading(
      "LEARNING THROUGH MAKING",
      "Lesson Plans",
      "Classroom-ready invitations with clear goals, flexible participation, and room to revise.",
    ) +
    `
    <div class="filters">
      <select id="band" aria-label="Developmental band"><option value="all">All developmental bands</option><option value="K">Kindergarten</option><option value="K–2">K–2</option></select>
      <input type="search" id="search" placeholder="Search lessons, standards, or supports" aria-label="Search lesson plans">
    </div>
    <p class="library-note">Original teaching plans aligned to the linked standards. Adapt timing and participation to your learners.</p>
    <div id="lessons" class="cards"></div>`;
  function filter() {
    const query = $("#search").value.toLowerCase();
    const visible = lessonPlans.filter(
      (plan) =>
        ($("#band").value === "all" || plan.band === $("#band").value) &&
        JSON.stringify(plan).toLowerCase().includes(query),
    );
    $("#lessons").innerHTML =
      visible
        .map(
          (plan) => `<article class="card lesson-card">
      <div class="art" aria-hidden="true">${plan.icon}</div>
      <p class="eyebrow">${plan.subject}</p><h2>${plan.title}</h2><p>${plan.summary}</p>
      <div class="tags">${plan.tags.map((tag) => `<span class="badge">${tag}</span>`).join("")}</div>
      <p class="standards-meta">${plan.standards.map((standard) => standard[0]).join(" · ")}</p>
      <div class="meta-footer"><span>${plan.band} · ${plan.duration}</span><button data-plan="${plan.id}" aria-label="Open ${plan.title}">Open plan →</button></div>
    </article>`,
        )
        .join("") ||
      '<p role="status">No matching lessons. Try another standard, support, or band.</p>';
    document
      .querySelectorAll("[data-plan]")
      .forEach(
        (button) => (button.onclick = () => openLesson(button.dataset.plan)),
      );
  }
  $("#band").onchange = filter;
  $("#search").oninput = filter;
  filter();
}

function openLesson(id) {
  const plan = lessonPlans.find((item) => item.id === id);
  if (!plan) return;
  const list = (items) =>
    `<ul>${items.map((item) => `<li>${item}</li>`).join("")}</ul>`;
  const dialog = document.createElement("dialog");
  dialog.className = "lesson-dialog";
  dialog.setAttribute("aria-labelledby", "lessonTitle");
  dialog.innerHTML = `<form method="dialog"><button class="close" aria-label="Close lesson plan">×</button></form>
    <article><p class="eyebrow">${plan.band} · ${plan.subject} · ${plan.duration}</p>
    <h2 id="lessonTitle">${plan.title}</h2><p>${plan.summary}</p>
    <section><h3>Standards alignment</h3><ul>${plan.standards.map(([code, description, url]) => `<li><a href="${url}" target="_blank" rel="noopener noreferrer">${code} ↗</a> — ${description}</li>`).join("")}</ul></section>
    <section><h3>Learning intentions</h3>${list(plan.objectives)}</section>
    <section class="lesson-sel"><h3>SEL in the making</h3><p>${plan.sel}</p></section>
    <section><h3>Materials & preparation</h3><p>${plan.materials}</p><p>${plan.preparation}</p></section>
    <section><h3>Activity sequence</h3><ol class="lesson-sequence">${plan.sequence.map(([label, text]) => `<li><h4>${label}</h4><p>${text}</p></li>`).join("")}</ol></section>
    <section><h3>Sensory & accessibility supports</h3>${list(plan.supports)}</section>
    <section><h3>Low-anxiety invitations</h3>${list(plan.prompts)}</section>
    <section><h3>Observe growth</h3><p>${plan.evidence}</p></section>
    <section><h3>Extend the exploration</h3><p>${plan.extension}</p></section>
    <section><h3>Bring it home</h3><p>${plan.home}</p></section>
    <section><h3>Safe making</h3><p>${plan.safety}</p></section>
    <button class="primary" id="useLesson">Use in Maker Studio →</button></article>`;
  document.body.append(dialog);
  dialog.querySelector("#useLesson").onclick = () => {
    save("snow-active-lesson", id);
    dialog.close();
    if (location.hash === "#studio") navigate("studio");
    else location.hash = "studio";
  };
  dialog.addEventListener("close", () => dialog.remove());
  dialog.showModal();
}

function studio() {
  const selected = read("snow-active-lesson", "habitats");
  const plan =
    lessonPlans.find((item) => item.id === selected) || lessonPlans[0];
  const record = read("snow-work-" + plan.id, { stage: 0, notes: "" });
  main.innerHTML =
    heading(
      "CHOOSE · MAKE · NOTICE",
      "Maker Studio Workspace",
      "Plan a small experiment, work at your pace, and keep a reflection.",
    ) +
    `
    <div class="studio-grid"><section class="card">
      <label for="activeLesson">Today’s invitation</label>
      <select id="activeLesson">${lessonPlans.map((item) => `<option value="${item.id}" ${item.id === plan.id ? "selected" : ""}>${item.title}</option>`).join("")}</select>
      <div class="studio-plan"><span class="badge">${plan.band} · ${plan.subject}</span><h2>${plan.title}</h2><p>${plan.summary}</p><button id="studioPlan">Read full lesson</button></div>
      <h3>Your visual schedule</h3><div class="steps" aria-label="Making stages">${["Choose & plan", "Make & try", "Notice & reflect"].map((label, index) => `<button data-stage="${index}" class="${record.stage === index ? "current" : ""}" aria-pressed="${record.stage === index}">${index + 1}. ${label}</button>`).join("")}</div>
      <p id="stagePrompt" role="status"></p>
      <label for="makerNotes">Ideas, sketches to describe, or things you noticed</label><textarea id="makerNotes" placeholder="An idea I tried… A change I might make…">${escape(record.notes)}</textarea>
      <div class="actions"><button id="saveNotes" class="primary">Save reflection</button><button id="studioBreak">Take a quiet break</button></div>
      <p class="library-note">This workspace saves on this device. Sharing a reflection is always optional.</p>
    </section><section class="card"><p class="eyebrow">MATERIALS & SUPPORT</p><h2>Make room for your way.</h2><p>${plan.materials}</p><h3>You can choose</h3><ul>${plan.supports.map((item) => `<li>${item}</li>`).join("")}</ul><div class="recommendation"><h3>A gentle invitation</h3><p>${plan.prompts[0]}</p></div><button id="studioCompanion">Open play companion →</button><div class="recommendation"><h3>Practice before making together</h3><p>Rehearse sharing a tool or asking for a sensory support. Bring your own words, family routines, or a quiet way to join in.</p><a href="#together?scene=${plan.id === "sensory" ? "space" : "sharing"}&band=younger&cast=buddy">Open a related role-play →</a></div></section></div>`;
  const prompts = [
    "Choose materials that feel comfortable. Plan one idea you would like to try.",
    "Try one small change. You can ask for help or pause whenever you like.",
    "What did you notice? Show, tell, write, or keep thinking.",
  ];
  function stage(index) {
    record.stage = index;
    $("#stagePrompt").textContent = prompts[index];
    document.querySelectorAll("[data-stage]").forEach((button) => {
      button.classList.toggle("current", +button.dataset.stage === index);
      button.setAttribute(
        "aria-pressed",
        String(+button.dataset.stage === index),
      );
    });
  }
  stage(record.stage);
  document.querySelectorAll("[data-stage]").forEach(
    (button) =>
      (button.onclick = () => {
        stage(+button.dataset.stage);
        record.notes = $("#makerNotes").value;
        save("snow-work-" + plan.id, record);
      }),
  );
  $("#activeLesson").onchange = (event) => {
    save("snow-active-lesson", event.target.value);
    studio();
  };
  $("#studioPlan").onclick = () => openLesson(plan.id);
  $("#makerNotes").oninput = (event) => {
    record.notes = event.target.value;
    save("snow-work-" + plan.id, record);
  };
  $("#saveNotes").onclick = () => {
    record.notes = $("#makerNotes").value;
    save("snow-work-" + plan.id, record);
    toast("Your reflection is saved on this device.");
  };
  $("#studioBreak").onclick = () => {
    $("#stagePrompt").textContent =
      "Take your time. Choose a stage whenever you feel ready to return.";
    speak("Take your time. We can return when you feel ready.");
  };
  $("#studioCompanion").onclick = () => {
    location.hash = "companion";
  };
}
